library(ggseg)
library(ggseg.formats)

ggplot() +
  geom_brain(
    atlas = dk(),
    aes(fill = label),
    position = position_brain(hemi ~ view),
    show.legend = FALSE
  ) +
  scale_fill_manual(
    values = atlas_palette(dk()),
    na.value = "grey80"
  ) +
  theme_void()
```
